import { test } from "node:test";
import assert from "node:assert/strict";
import { validateFeed, verifyArtifact } from "../prepare-update.mjs";

// Independent public fixture from tauri-plugin-updater 2.14.1 (Apache-2.0/MIT),
// generated by its CLI, not by this verifier. No private signing key is retained.
const keyText =
  "untrusted comment: minisign public key: A49EF4746FA6E6D7\nRWTX5qZvdPSepDGWg2bz8n6ArQnBMwgQK1geVosorcbLzcunD+KJ+cYe";
const signatureText =
  "untrusted comment: signature from tauri secret key\nRUTX5qZvdPSepPF2zsjvP/L/TQtBLRnWRvaq+4omK1UEugtQp/USrGiI1v762sDy3id3aor7bRC9ETyeot6lMHHrWoZ5hjUM1Qc=\ntrusted comment: timestamp:1791649051\tfile:payload\tversion:2.0.0\nDDq2CLOEl5cQmC2eJRHlnZPVViOZsu1CjpPKQoei4A/XBfkDqGO0B+QMrcrHgEQ5qV3mne75tdFWhJpqUXh9AA==";
const encode = (s) => Buffer.from(s).toString("base64");
test("accepts a Tauri CLI signature and rejects corrupt bytes, tampered version and replay", () => {
  verifyArtifact(
    Buffer.from("test"),
    encode(signatureText),
    encode(keyText),
    "2.0.0",
  );
  assert.throws(() =>
    verifyArtifact(
      Buffer.from("changed"),
      encode(signatureText),
      encode(keyText),
      "2.0.0",
    ),
  );
  assert.throws(() =>
    verifyArtifact(
      Buffer.from("test"),
      encode(signatureText.replace("version:2.0.0", "version:3.0.0")),
      encode(keyText),
      "3.0.0",
    ),
  );
  assert.throws(() =>
    verifyArtifact(
      Buffer.from("test"),
      encode(signatureText),
      encode(keyText),
      "3.0.0",
    ),
  );
});
test("disabled feed is explicit; active feeds require valid, bounded official assets", () => {
  validateFeed({ version: "0.0.0", platforms: {} });
  assert.throws(() => validateFeed({ version: "1.0.0", platforms: {} }));
  const feed = {
    version: "2.0.0",
    platforms: {
      "darwin-aarch64-app": {
        url: "https://github.com/FerMatter/fermatter.github.io/releases/download/v2.0.0/FerMatter.app.tar.gz",
        signature: encode(signatureText),
        size: 4,
        sha256: "a".repeat(64),
      },
    },
  };
  validateFeed(feed);
  assert.throws(() => validateFeed({ ...feed, version: "2.0.0-rc.1" }));
  const entry = feed.platforms["darwin-aarch64-app"];
  for (const patch of [
    { size: 0 },
    { size: 1_000_000_001 },
    { signature: "" },
    { sha256: "x" },
    { url: entry.url.replace("github.com", "example.com") },
    { url: entry.url.replace("v2.0.0/", "v1.0.0/") },
    { url: entry.url.replace(".app.tar.gz", ".exe") },
  ]) {
    assert.throws(() =>
      validateFeed({
        ...feed,
        platforms: { "darwin-aarch64-app": { ...entry, ...patch } },
      }),
    );
  }
});
